// Parameters
// ---------------------------------------------------------------------------

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Loops {
    pub b1_supply_response: f64,
    pub b2_backlash: f64,
    pub b3_affordability: f64,
    pub r1_recursive_ai: f64,
    pub r2_robot_bootstrap: f64,
    pub r3_capex_momentum: f64,
    pub b4_credit: f64,
}

impl Default for Loops {
    fn default() -> Self {
        Loops {
            b1_supply_response: 1.0,
            b2_backlash: 1.0,
            b3_affordability: 1.0,
            r1_recursive_ai: 1.0,
            r2_robot_bootstrap: 1.0,
            r3_capex_momentum: 1.0,
            b4_credit: 1.0,
        }
    }
}

